//! The speech catalog (catalog.json in the lang MCP folder, generated by
//! tools/speech-catalog.py): languages, voices and models with pinned URL, size and
//! sha256.

use serde::Deserialize;
use std::collections::BTreeMap;
use std::path::PathBuf;

#[derive(Clone, Debug, Default, Deserialize)]
#[serde(default)]
pub struct LangInfo {
    pub name: String,
    pub hear: bool,
    pub voices: Vec<String>,
    pub default_voice: String,
}

#[derive(Clone, Debug, Default, Deserialize)]
#[serde(default)]
pub struct File {
    pub kind: String,
    pub url: String,
    pub size: u64,
    pub sha256: String,
    pub note: String,
}

#[derive(Clone, Debug, Default, Deserialize)]
#[serde(default)]
pub struct Voice {
    pub kind: String,
    pub langs: Vec<String>,
    pub locale: String,
    pub speaker: String,
    pub quality: String,
    pub note: String,
    pub url: String,
    pub size: u64,
    pub sha256: String,
}

#[derive(Clone, Debug, Default, Deserialize)]
#[serde(default)]
pub struct Asr {
    pub kind: String,
    /// Languages it transcribes; empty = every language Whisper knows.
    pub langs: Vec<String>,
    pub size_name: String,
    pub note: String,
    /// A .tar.bz2 to unpack, or (empty) `files` downloaded one by one.
    pub url: String,
    pub size: u64,
    pub sha256: String,
    /// The model's files, each saved under the name its URL ends with.
    pub files: Vec<File>,
}

impl Asr {
    /// Download size of the whole model.
    pub fn total_size(&self) -> u64 {
        self.size + self.files.iter().map(|f| f.size).sum::<u64>()
    }
}

#[derive(Clone, Debug, Default, Deserialize)]
#[serde(default)]
pub struct Catalog {
    pub languages: BTreeMap<String, LangInfo>,
    pub voices: BTreeMap<String, Voice>,
    pub asr: BTreeMap<String, Asr>,
    pub extras: BTreeMap<String, File>,
}

/// $BIA_SPEECH_CATALOG, else catalog.json next to the running MCP (bin/<arch>/../../),
/// else the lang MCP's copy in /home/bia/MCPs/lang.
pub fn path() -> PathBuf {
    if let Ok(p) = std::env::var("BIA_SPEECH_CATALOG") {
        return PathBuf::from(p);
    }
    let shipped = PathBuf::from("/home/bia/MCPs/lang/catalog.json");
    let exe = std::env::current_exe().unwrap_or_default();
    let mut dir = exe.parent().map(PathBuf::from).unwrap_or_default();
    for _ in 0..3 {
        let c = dir.join("catalog.json");
        if c.exists() {
            return c;
        }
        if !dir.pop() {
            break;
        }
    }
    shipped
}

pub fn load() -> Result<Catalog, String> {
    let p = path();
    let text = std::fs::read_to_string(&p).map_err(|e| format!("catalog {}: {e}", p.display()))?;
    serde_json::from_str(&text).map_err(|e| format!("catalog {}: {e}", p.display()))
}

pub fn mb(bytes: u64) -> String {
    if bytes >= 1_000_000 {
        format!("{} MB", bytes / 1_000_000)
    } else {
        format!("{} KB", bytes.div_ceil(1000))
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn shipped_catalog_parses() {
        let p = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../flash/MCPs/lang/catalog.json");
        let c: Catalog = serde_json::from_str(&std::fs::read_to_string(p).unwrap()).unwrap();
        assert!(c.languages.len() >= 99);
        let ru = &c.languages["ru"];
        assert!(ru.hear && !ru.voices.is_empty());
        assert!(c.voices.contains_key(&ru.default_voice));
        assert!(c.voices.values().all(|v| v.sha256.len() == 64 && v.size > 0 && v.url.starts_with("https://")));
        // one archive, or files each pinned
        assert!(c.asr.values().all(|v| if v.files.is_empty() {
            v.sha256.len() == 64 && v.url.starts_with("https://")
        } else {
            v.url.is_empty() && v.files.iter().all(|f| f.sha256.len() == 64 && f.size > 0 && f.url.starts_with("https://"))
        }));
        let fa = &c.asr["shenava-fa"];
        assert_eq!((fa.kind.as_str(), fa.langs.as_slice()), ("nemo_ctc", &["fa".to_string()][..]));
        assert!(fa.files.iter().any(|f| f.url.ends_with("/model.onnx")) && fa.files.iter().any(|f| f.url.ends_with("/tokens.txt")));
        assert!(fa.total_size() > 100_000_000);
        assert!(c.extras.contains_key("speaker-campplus"));
        assert!(c.languages["en"].default_voice == crate::registry::BUNDLED_VOICE);
    }
}
